14

15 int main(void) {

16     int n;

17     cin >> n;


18

19     for (int i = 0; i < n - 1; ++i) {

20         int a, b, c;

21         cin >> a >> b >> c;

22         a--, b--;

23         tree[a].push_back({b, c});

24         tree[b].push_back({a, c});

25     }


26

27     int q, k;

28     cin >> q >> k;

29     k--;


30

31     dfs(k, -1, 0);

32     for (int i = 0; i < q; ++i) {

33         int x, y;

34         cin >> x >> y;

35         x--, y--;

36         cout << depth[x] + depth[y] << endl;

37     }


38

39     return 0;
40 }





